#!/usr/bin/env node
// Builds YOUR personal playlist(s) from the playlists generated by `npm run playlist:generate`.
// Usage:
//   node my-playlist/build.mjs                  build using my-playlist/preferences.json
//   node my-playlist/build.mjs --list categories|countries|languages|stats
//   node my-playlist/build.mjs --config path/to/other.json
// No extra dependencies. Needs Node 18+.

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const HERE = path.dirname(fileURLToPath(import.meta.url))
const ROOT = path.resolve(HERE, '..')
const DATA = path.join(ROOT, 'temp/data')
const SOURCE = path.join(ROOT, '.gh-pages/index.m3u')

const args = process.argv.slice(2)
const argVal = name => {
  const i = args.indexOf(name)
  return i >= 0 ? args[i + 1] : undefined
}

function die(msg) {
  console.error(`ERROR: ${msg}`)
  process.exit(1)
}

function loadJson(file) {
  if (!fs.existsSync(file)) {
    die(`${path.relative(ROOT, file)} not found. Run "npm run api:load" first (step 3 of the guide).`)
  }
  return JSON.parse(fs.readFileSync(file, 'utf8'))
}

// ---------- parsing ----------
function parseM3U(text) {
  const lines = text.split(/\r?\n/)
  const entries = []
  let cur = null
  for (const raw of lines) {
    const line = raw.trim()
    if (!line || line.startsWith('#EXTM3U')) continue
    if (line.startsWith('#EXTINF')) {
      cur = { extinf: line, opts: [], url: '' }
    } else if (line.startsWith('#') && cur) {
      cur.opts.push(line)
    } else if (cur) {
      cur.url = line
      entries.push(cur)
      cur = null
    }
  }
  return entries.map(e => {
    const attr = k => (e.extinf.match(new RegExp(`${k}="([^"]*)"`)) || [])[1] || ''
    const comma = e.extinf.indexOf(',', e.extinf.lastIndexOf('"') + 1)
    const title = comma >= 0 ? e.extinf.slice(comma + 1).trim() : ''
    const tvgId = attr('tvg-id')
    const [channelId, feedId] = tvgId.split('@')
    const height = Number((title.match(/\((\d{3,4})[pi]\)/) || [])[1] || 0)
    return {
      ...e,
      title,
      tvgId,
      channelId,
      feedId,
      logo: attr('tvg-logo'),
      groupTitle: attr('group-title'),
      height,
      geoBlocked: /\[Geo-blocked\]/i.test(title),
      not247: /\[Not 24\/7\]/i.test(title)
    }
  })
}

const q = s => String(s ?? '').replace(/"/g, "'")

function serialize(entries, headerUrl) {
  const out = [headerUrl ? `#EXTM3U x-tvg-url="${headerUrl}"` : '#EXTM3U']
  for (const e of entries) {
    let line = `#EXTINF:-1 tvg-id="${q(e.tvgId)}"`
    if (e.logo) line += ` tvg-logo="${q(e.logo)}"`
    line += ` group-title="${q(e.group)}",${e.title}`
    out.push(line, ...e.opts, e.url)
  }
  return out.join('\r\n') + '\r\n'
}

// ---------- helpers ----------
const lc = a => (a || []).map(x => String(x).toLowerCase())
const regexes = list =>
  (list || []).map(r => {
    try {
      return new RegExp(r, 'i')
    } catch {
      die(`Invalid regular expression in preferences: ${r}`)
    }
  })

async function loadExtra(src) {
  let text
  if (/^https?:\/\//i.test(src)) {
    const res = await fetch(src)
    if (!res.ok) throw new Error(`HTTP ${res.status}`)
    text = await res.text()
  } else {
    text = fs.readFileSync(path.resolve(ROOT, src), 'utf8')
  }
  return parseM3U(text)
}

// ---------- main ----------
async function main() {
  const channels = loadJson(path.join(DATA, 'channels.json'))
  const feeds = loadJson(path.join(DATA, 'feeds.json'))
  const categories = loadJson(path.join(DATA, 'categories.json'))
  const countries = loadJson(path.join(DATA, 'countries.json'))
  const languages = loadJson(path.join(DATA, 'languages.json'))

  const channelById = new Map(channels.map(c => [c.id, c]))
  const feedByStreamId = new Map(feeds.map(f => [`${f.channel}@${f.id}`, f]))
  const countryName = new Map(countries.map(c => [c.code.toLowerCase(), c.name]))
  const languageName = new Map(languages.map(l => [l.code.toLowerCase(), l.name]))
  const categoryName = new Map(categories.map(c => [c.id, c.name]))

  if (!fs.existsSync(SOURCE)) {
    die('.gh-pages/index.m3u not found. Run "npm run playlist:generate" first (step 4 of the guide).')
  }
  const all = parseM3U(fs.readFileSync(SOURCE, 'utf8')).filter(e => e.channelId)
  for (const e of all) {
    e.channel = channelById.get(e.channelId)
    e.feed = feedByStreamId.get(e.tvgId)
    e.country = (e.channel?.country || '').toLowerCase()
    e.cats = lc(e.channel?.categories)
    e.langs = lc(e.feed?.languages)
  }

  // ----- --list mode -----
  const listWhat = argVal('--list')
  if (listWhat) {
    const count = (keyFn, names) => {
      const m = new Map()
      for (const e of all) for (const k of [].concat(keyFn(e))) if (k) m.set(k, (m.get(k) || 0) + 1)
      return [...m.entries()].sort((a, b) => b[1] - a[1]).map(([k, n]) => `${String(n).padStart(5)}  ${k.padEnd(10)} ${names.get(k) || ''}`)
    }
    if (listWhat === 'categories') console.log(count(e => e.cats, new Map([...categoryName].map(([k, v]) => [k, v]))).join('\n'))
    else if (listWhat === 'countries') console.log(count(e => e.country, countryName).join('\n'))
    else if (listWhat === 'languages') console.log(count(e => e.langs, languageName).join('\n'))
    else if (listWhat === 'stats') {
      console.log(`channels with a working-candidate stream in index.m3u: ${all.length}`)
      console.log(`geo-blocked: ${all.filter(e => e.geoBlocked).length}`)
      console.log(`not 24/7:    ${all.filter(e => e.not247).length}`)
      console.log(`1080p+:      ${all.filter(e => e.height >= 1080).length}`)
      console.log(`720p+:       ${all.filter(e => e.height >= 720).length}`)
    } else die('--list takes: categories | countries | languages | stats')
    console.log('\n(count = number of channels in the public index; codes are what you put in preferences.json)')
    return
  }

  // ----- load preferences -----
  const cfgPath = path.resolve(argVal('--config') || path.join(HERE, 'preferences.json'))
  const cfg = loadJson(cfgPath)
  const f = cfg.filters || {}
  const inc = { cat: lc(f.categories_include), cty: lc(f.countries_include), lng: lc(f.languages_include) }
  const exc = { cat: lc(f.categories_exclude), cty: lc(f.countries_exclude), lng: lc(f.languages_exclude) }
  const nameInc = regexes(f.name_include)
  const nameExc = regexes(f.name_exclude)
  const alwaysIds = new Set(cfg.always_include_ids || [])
  const blockIds = new Set(cfg.blocklist_ids || [])
  const anyOf = (have, want) => have.some(x => want.includes(x))

  const warn = (list, valid, singular, plural) => {
    for (const v of list) {
      if (!valid.has(v)) console.warn(`WARNING: unknown ${singular} "${v}" (see: node my-playlist/build.mjs --list ${plural})`)
    }
  }
  warn(inc.cat.concat(exc.cat), new Set(categories.map(c => c.id)), 'category', 'categories')
  warn(inc.cty.concat(exc.cty), new Set(countries.map(c => c.code.toLowerCase())), 'country', 'countries')
  warn(inc.lng.concat(exc.lng), new Set(languages.map(l => l.code.toLowerCase())), 'language', 'languages')

  const kept = all.filter(e => {
    if (alwaysIds.has(e.tvgId) || alwaysIds.has(e.channelId)) return true
    if (blockIds.has(e.tvgId) || blockIds.has(e.channelId)) return false
    if (f.exclude_closed !== false && e.channel?.closed) return false
    if (f.allow_geo_blocked === false && e.geoBlocked) return false
    if (f.allow_not_247 === false && e.not247) return false
    if (f.min_height && e.height && e.height < f.min_height) return false
    if (f.min_height && !e.height && f.drop_unknown_quality) return false
    if (f.max_height && e.height > f.max_height) return false
    if (inc.cat.length && !anyOf(e.cats, inc.cat)) return false
    if (inc.cty.length && !inc.cty.includes(e.country)) return false
    if (inc.lng.length && !anyOf(e.langs, inc.lng)) return false
    if (exc.cat.length && anyOf(e.cats, exc.cat)) return false
    if (exc.cty.length && exc.cty.includes(e.country)) return false
    if (exc.lng.length && anyOf(e.langs, exc.lng)) return false
    if (nameInc.length && !nameInc.some(r => r.test(e.title))) return false
    if (nameExc.length && nameExc.some(r => r.test(e.title))) return false
    return true
  })

  // ----- grouping -----
  const o = cfg.output || {}
  const priority = lc(o.category_priority)
  const groupBy = o.group_by || 'category'
  for (const e of kept) {
    // primary category: your priority list first, but never one you excluded or didn't include
    const allowed = e.cats.filter(c => (!inc.cat.length || inc.cat.includes(c)) && !exc.cat.includes(c))
    e.primaryCat = priority.find(p => allowed.includes(p)) || allowed.slice().sort()[0] || e.cats.slice().sort()[0] || 'uncategorized'
    if (groupBy === 'country') e.group = countryName.get(e.country) || 'Other'
    else if (groupBy === 'none') e.group = o.single_group_name || 'Channels'
    else {
      e.group = categoryName.get(e.primaryCat) || 'Uncategorized'
    }
  }

  // ----- optional group overrides, e.g. put football channels in their own "Football" group -----
  // output.group_overrides: [{ "title_regex": "...", "categories": ["sports"], "group": "Football" }]
  // first matching rule wins; "categories" (optional) must overlap the channel's categories
  const rules = (o.group_overrides || []).map(r => ({
    re: r.title_regex ? new RegExp(r.title_regex, 'i') : null,
    cats: lc(r.categories),
    group: r.group
  }))
  if (rules.length) {
    for (const e of kept) {
      const hit = rules.find(r => (!r.re || r.re.test(e.title)) && (!r.cats.length || anyOf(e.cats, r.cats)))
      if (hit) e.group = hit.group
    }
  }

  // ----- extras (your own M3U files / URLs) -----
  const extras = []
  for (const src of cfg.extra_playlists || []) {
    try {
      const items = await loadExtra(src)
      for (const e of items) {
        e.group = e.groupTitle || o.extra_group_name || 'Custom'
        if (nameExc.length && nameExc.some(r => r.test(e.title))) continue
        extras.push(e)
      }
      console.log(`extra playlist loaded: ${src} (${items.length} entries)`)
    } catch (err) {
      console.warn(`WARNING: could not load extra playlist ${src}: ${err.message}`)
    }
  }

  // ----- sort / limit -----
  const sortKey = o.sort_by || 'group_then_name'
  const cmpName = (a, b) => a.title.localeCompare(b.title)
  const order = (o.group_order || []).map(x => x.toLowerCase())
  const rank = g => {
    const i = order.indexOf(String(g).toLowerCase())
    return i === -1 ? order.length : i
  }
  kept.sort(sortKey === 'name' ? cmpName : (a, b) => rank(a.group) - rank(b.group) || a.group.localeCompare(b.group) || cmpName(a, b))
  let finalList = kept
  if (cfg.max_channels && finalList.length > cfg.max_channels) finalList = finalList.slice(0, cfg.max_channels)
  finalList = finalList.concat(extras)

  // ----- write -----
  const outDir = path.resolve(ROOT, o.directory || 'my-playlist/dist')
  fs.mkdirSync(outDir, { recursive: true })
  const baseName = (o.filename || 'my-iptv') + '.m3u'
  fs.writeFileSync(path.join(outDir, baseName), serialize(finalList, cfg.epg_url))
  console.log(`wrote ${path.relative(ROOT, path.join(outDir, baseName))}  (${finalList.length} channels)`)

  if (o.also_split_by === 'category' || o.also_split_by === 'country') {
    const buckets = new Map()
    for (const e of finalList) {
      const key = o.also_split_by === 'country' ? e.country || 'other' : (e.primaryCat || 'custom')
      if (!buckets.has(key)) buckets.set(key, [])
      buckets.get(key).push(e)
    }
    const sub = path.join(outDir, `by-${o.also_split_by}`)
    fs.mkdirSync(sub, { recursive: true })
    for (const [k, list] of buckets) fs.writeFileSync(path.join(sub, `${k}.m3u`), serialize(list, cfg.epg_url))
    console.log(`wrote ${buckets.size} split files in ${path.relative(ROOT, sub)}/`)
  }

  if (finalList.length === 0) console.warn('WARNING: your filters matched 0 channels. Loosen them in preferences.json.')
}

main().catch(err => die(err.stack || String(err)))
